"""In-memory exam session state and the per-turn orchestration."""

import time
import uuid
from dataclasses import dataclass, field
from datetime import date

from agents import chair, professors
from schemas import Blueprint, ChairDecision, Language, ProfessorAssessment, Topic, Turn


@dataclass
class ExamSession:
    blueprint: Blueprint
    pages: list[str]
    language: Language = "en"
    num_questions: int = 6
    exam_date: date | None = None
    id: str = field(default_factory=lambda: uuid.uuid4().hex[:12])
    turns: list[Turn] = field(default_factory=list)
    report: dict | None = None

    # --- state helpers used by the agents ---

    @property
    def current_turn(self) -> Turn:
        return self.turns[-1]

    @property
    def current_topic(self) -> Topic:
        topic_id = self.turns[-1].topic_id if self.turns else self.blueprint.topics[0].id
        return self.topic(topic_id)

    def topic(self, topic_id: str) -> Topic:
        return next((t for t in self.blueprint.topics if t.id == topic_id), self.blueprint.topics[0])

    def slide_text(self, refs: list[int], limit: int = 6000) -> str:
        chunks = [f"[Slide {r}] {self.pages[r - 1]}" for r in refs if 0 < r <= len(self.pages)]
        return "\n".join(chunks)[:limit] or "(no slide text available)"

    def answered_count(self) -> int:
        return sum(1 for t in self.turns if t.answer is not None)

    def questions_on_current_topic(self) -> int:
        n = 0
        for t in reversed(self.turns):
            if t.topic_id != self.current_topic.id:
                break
            n += 1
        return n

    def covered_topic_ids(self) -> list[str]:
        return list(dict.fromkeys(t.topic_id for t in self.turns))

    def next_topic_id(self) -> str:
        covered = set(self.covered_topic_ids())
        for t in self.blueprint.topics:
            if t.id not in covered:
                return t.id
        # Every topic covered: revisit the one after the current topic.
        ids = [t.id for t in self.blueprint.topics]
        return ids[(ids.index(self.current_topic.id) + 1) % len(ids)]

    def transcript(self, last: int = 8) -> str:
        lines = []
        for t in self.turns[-last:]:
            lines.append(f"[{t.speaker}, topic {t.topic_id}] {t.question}")
            if t.answer is not None:
                lines.append(f"[student] {t.answer}")
        return "\n".join(lines) or "(exam not started)"

    # --- turn orchestration ---

    async def start(self) -> ChairDecision:
        decision = await chair.opening(self)
        self.turns.append(Turn(speaker=decision.next_speaker, question=decision.question,
                               topic_id=decision.topic_id, reasoning=decision.reasoning))
        return decision

    async def answer(self, text: str) -> tuple[list[ProfessorAssessment], ChairDecision, dict]:
        """Record the student's answer, run the panel, and queue the next question."""
        timings: dict[str, float] = {}
        self.current_turn.answer = text.strip() or "(no answer)"

        t0 = time.perf_counter()
        assessments = await professors.assess_all(self)
        timings["professors_s"] = round(time.perf_counter() - t0, 2)
        self.current_turn.assessments = assessments

        t0 = time.perf_counter()
        decision = await chair.decide(self, assessments)
        timings["chair_s"] = round(time.perf_counter() - t0, 2)

        if not decision.end_exam:
            self.turns.append(Turn(speaker=decision.next_speaker, question=decision.question,
                                   topic_id=decision.topic_id, reasoning=decision.reasoning))
        return assessments, decision, timings


SESSIONS: dict[str, ExamSession] = {}

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

// The backend runs on 8077 (see README); /api is proxied there in dev.
export default defineConfig({
  plugins: [react(), tailwindcss()],
  server: {
    proxy: {
      '/api': process.env.VITE_API_URL ?? 'http://localhost:8077',
    },
  },
})

@import "tailwindcss";

@theme {
  --font-sans: "Plus Jakarta Sans", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Fraunces", ui-serif, Georgia, serif;

  --color-paper: #faf7f2;
  --color-ink: #1f2430;
  --color-muted: #5b6170;

  --color-theorist: #4f46e5;
  --color-theorist-soft: #eef2ff;
  --color-practitioner: #0f9d76;
  --color-practitioner-soft: #e7f7f1;
  --color-skeptic: #d9480f;
  --color-skeptic-soft: #fff1e8;
}

body {
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

:focus-visible {
  outline: 3px solid var(--color-theorist);
  outline-offset: 3px;
  border-radius: 12px;
}

@keyframes bar {
  0%, 100% { transform: scaleY(0.3); }
  50% { transform: scaleY(1); }
}
.speaking-bar { animation: bar 0.9s ease-in-out infinite; transform-origin: bottom; }

@keyframes dot {
  0%, 80%, 100% { opacity: 0.25; transform: translateY(0); }
  40% { opacity: 1; transform: translateY(-3px); }
}
.thinking-dot { animation: dot 1.2s ease-in-out infinite; }

@keyframes ripple {
  0% { transform: scale(1); opacity: 0.45; }
  100% { transform: scale(1.6); opacity: 0; }
}
.mic-ripple { animation: ripple 1.2s ease-out infinite; }

.flip-card { perspective: 1000px; }
.flip-inner { transition: transform 0.5s; transform-style: preserve-3d; }
.flip-card[data-flipped="true"] .flip-inner { transform: rotateY(180deg); }
.flip-face { backface-visibility: hidden; }
.flip-back { transform: rotateY(180deg); }

@media (prefers-reduced-motion: reduce) {
  .speaking-bar, .thinking-dot, .mic-ripple { animation: none; }
  .flip-inner { transition: none; }
}

export type ProfessorId = 'theorist' | 'practitioner' | 'skeptic'
export type Language = 'en' | 'de'

export interface Topic {
  id: string
  title: string
  key_concepts: string[]
  slide_refs: number[]
}

export interface Turn {
  speaker: ProfessorId
  question: string
  topic_id: string
  topic_title: string
  reasoning: string
  audio_url: string
  question_number: number
  total_questions: number
  end_exam: boolean
}

export interface Assessment {
  professor: ProfessorId
  score_0_to_10: number
  what_was_good: string
  gaps: string[]
  bluff_signal: number
  proposed_followup: string
  urgency: number
  move_to_new_topic: boolean
}

export interface SessionResponse {
  session_id: string
  language: Language
  blueprint: { course_title: string; topics: Topic[] }
  turn: Turn
}

export interface AnswerResponse {
  transcript: string
  assessments: Assessment[]
  turn: Turn
  timings: Record<string, number>
}

export interface ReportResponse {
  report: {
    deliberation: { professor: ProfessorId; text: string }[]
    grade: number
    strengths: string[]
    per_topic: { topic_id: string; score: number; feedback: string }[]
    weakest_topics: string[]
  }
  plan: {
    sessions: { date: string; duration_min: number; topic_ids: string[]; goal: string }[]
    flashcards: { front: string; back: string; topic_id: string }[]
  }
  ics_url: string
  course_title: string
  topics: Record<string, string>
  exam_date: string | null
}

async function request<T>(url: string, body?: FormData): Promise<T> {
  let res: Response
  try {
    res = await fetch(url, { method: 'POST', body })
  } catch {
    throw new Error("We can't reach the Viva server. Is the backend running?")
  }
  if (!res.ok) {
    let detail = 'Something went wrong. Please try again.'
    try {
      detail = (await res.json()).detail ?? detail
    } catch { /* keep default */ }
    throw new Error(detail)
  }
  return res.json()
}

export function createSession(pdf: File, examDate: string, numQuestions: number, language: Language) {
  const fd = new FormData()
  fd.append('pdf', pdf)
  if (examDate) fd.append('exam_date', examDate)
  fd.append('num_questions', String(numQuestions))
  fd.append('language', language)
  return request<SessionResponse>('/api/session', fd)
}

export function sendAnswer(sessionId: string, answer: { audio?: Blob; text?: string; skip?: boolean }) {
  const fd = new FormData()
  if (answer.audio) fd.append('audio', answer.audio, 'answer.wav')
  if (answer.text) fd.append('text', answer.text)
  if (answer.skip) fd.append('skip', 'true')
  return request<AnswerResponse>(`/api/session/${sessionId}/answer`, fd)
}

export function getReport(sessionId: string) {
  return request<ReportResponse>(`/api/session/${sessionId}/report`)
}

// Records the microphone as 16-bit mono WAV. Gradium STT accepts WAV/PCM/Ogg-Opus,
// but not the WebM that MediaRecorder produces in Chrome, so we capture raw PCM ourselves.

const TARGET_RATE = 24000

export class WavRecorder {
  private ctx: AudioContext | null = null
  private stream: MediaStream | null = null
  private source: MediaStreamAudioSourceNode | null = null
  private processor: ScriptProcessorNode | null = null
  private chunks: Float32Array[] = []
  private recording = false
  onLevel: (level: number) => void = () => {}

  async init(): Promise<void> {
    if (this.ctx) return
    this.stream = await navigator.mediaDevices.getUserMedia({
      audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true },
    })
    this.ctx = new AudioContext()
    this.source = this.ctx.createMediaStreamSource(this.stream)
    this.processor = this.ctx.createScriptProcessor(4096, 1, 1)
    this.processor.onaudioprocess = (e) => {
      const input = e.inputBuffer.getChannelData(0)
      let sum = 0
      for (let i = 0; i < input.length; i++) sum += input[i] * input[i]
      this.onLevel(Math.min(1, Math.sqrt(sum / input.length) * 6))
      if (this.recording) this.chunks.push(new Float32Array(input))
    }
    this.source.connect(this.processor)
    this.processor.connect(this.ctx.destination)
  }

  async start(): Promise<void> {
    await this.init()
    await this.ctx!.resume()
    this.chunks = []
    this.recording = true
  }

  /** Stops recording; returns the WAV and its duration in seconds. */
  stop(): { wav: Blob; seconds: number } {
    this.recording = false
    const rate = this.ctx?.sampleRate ?? 48000
    const length = this.chunks.reduce((n, c) => n + c.length, 0)
    const merged = new Float32Array(length)
    let offset = 0
    for (const c of this.chunks) {
      merged.set(c, offset)
      offset += c.length
    }
    this.chunks = []
    const samples = downsample(merged, rate, TARGET_RATE)
    return { wav: encodeWav(samples, TARGET_RATE), seconds: length / rate }
  }

  close(): void {
    this.stream?.getTracks().forEach((t) => t.stop())
    this.ctx?.close()
    this.ctx = null
  }
}

function downsample(input: Float32Array, from: number, to: number): Float32Array {
  if (to >= from) return input
  const ratio = from / to
  const out = new Float32Array(Math.floor(input.length / ratio))
  for (let i = 0; i < out.length; i++) {
    const start = Math.floor(i * ratio)
    const end = Math.min(input.length, Math.floor((i + 1) * ratio))
    let sum = 0
    for (let j = start; j < end; j++) sum += input[j]
    out[i] = sum / Math.max(1, end - start)
  }
  return out
}

function encodeWav(samples: Float32Array, rate: number): Blob {
  const buffer = new ArrayBuffer(44 + samples.length * 2)
  const view = new DataView(buffer)
  const write = (o: number, s: string) => [...s].forEach((ch, i) => view.setUint8(o + i, ch.charCodeAt(0)))
  write(0, 'RIFF')
  view.setUint32(4, 36 + samples.length * 2, true)
  write(8, 'WAVE')
  write(12, 'fmt ')
  view.setUint32(16, 16, true)
  view.setUint16(20, 1, true) // PCM
  view.setUint16(22, 1, true) // mono
  view.setUint32(24, rate, true)
  view.setUint32(28, rate * 2, true)
  view.setUint16(32, 2, true)
  view.setUint16(34, 16, true)
  write(36, 'data')
  view.setUint32(40, samples.length * 2, true)
  for (let i = 0; i < samples.length; i++) {
    const s = Math.max(-1, Math.min(1, samples[i]))
    view.setInt16(44 + i * 2, s < 0 ? s * 0x8000 : s * 0x7fff, true)
  }
  return new Blob([buffer], { type: 'audio/wav' })
}

