import { useEffect, useRef, useState } from 'react'
import { createSession, type Language, type SessionResponse } from './api'
import { WavRecorder } from './recorder'
import { Avatar, PROFESSOR_IDS, PROFESSORS } from './professors'

const LENGTHS = [
  { n: 4, label: 'Quick', hint: 'about 5 min' },
  { n: 6, label: 'Standard', hint: 'about 8 min' },
  { n: 8, label: 'Full', hint: 'about 12 min' },
]

const LOADING_STEPS = [
  'Reading your slides…',
  'Finding the key topics…',
  'Writing the exam blueprint…',
  'The professors are taking their seats…',
]

function daysUntil(iso: string): number | null {
  if (!iso) return null
  const ms = new Date(iso + 'T00:00:00').getTime() - new Date(new Date().toDateString()).getTime()
  return Math.round(ms / 86_400_000)
}

export default function Setup({ onReady }: { onReady: (s: SessionResponse) => void }) {
  const [file, setFile] = useState<File | null>(null)
  const [dragging, setDragging] = useState(false)
  const [examDate, setExamDate] = useState('')
  const [length, setLength] = useState(4)
  const [language, setLanguage] = useState<Language>('en')
  const [loading, setLoading] = useState(false)
  const [step, setStep] = useState(0)
  const [error, setError] = useState('')
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (!loading) return
    const id = setInterval(() => setStep((s) => Math.min(s + 1, LOADING_STEPS.length - 1)), 3500)
    return () => clearInterval(id)
  }, [loading])

  const pick = (f: File | undefined) => {
    setError('')
    if (!f) return
    if (f.type !== 'application/pdf' && !f.name.toLowerCase().endsWith('.pdf')) {
      setError('Please choose a PDF of your lecture slides.')
      return
    }
    setFile(f)
  }

  const start = async () => {
    if (!file) return
    setLoading(true)
    setStep(0)
    setError('')
    try {
      onReady(await createSession(file, examDate, length, language))
    } catch (e) {
      setError((e as Error).message)
      setLoading(false)
    }
  }

  const days = daysUntil(examDate)
  const today = new Date().toISOString().slice(0, 10)

  if (loading) {
    return (
      <div className="mx-auto flex min-h-[70vh] max-w-md flex-col items-center justify-center px-4 text-center" role="status" aria-live="polite">
        <div className="mb-8 flex -space-x-3">
          {PROFESSOR_IDS.map((id) => <Avatar key={id} id={id} size="lg" />)}
        </div>
        <p className="font-display text-2xl font-semibold">{LOADING_STEPS[step]}</p>
        <p className="mt-3 text-muted">This takes about 15 seconds. Take a breath. You've got this.</p>
        <div className="mt-6 h-1.5 w-56 overflow-hidden rounded-full bg-black/5">
          <div className="h-full rounded-full bg-theorist transition-all duration-1000" style={{ width: `${((step + 1) / LOADING_STEPS.length) * 100}%` }} />
        </div>
      </div>
    )
  }

  return (
    <div className="mx-auto max-w-3xl px-4 pb-16 pt-10 sm:pt-16">
      <header className="mb-10 text-center">
        <h1 className="font-display text-5xl font-bold tracking-tight sm:text-6xl">Viva</h1>
        <p className="mx-auto mt-4 max-w-xl text-lg text-muted">
          Rehearse your oral exam out loud with a panel of three professors, built from <em>your own</em> lecture slides.
        </p>
      </header>

      <section aria-label="Meet the panel" className="mb-10 grid gap-3 sm:grid-cols-3">
        {PROFESSOR_IDS.map((id) => (
          <div key={id} className="flex items-center gap-3 rounded-2xl bg-white p-4 shadow-sm ring-1 ring-black/5">
            <Avatar id={id} />
            <div>
              <p className={`font-semibold ${PROFESSORS[id].text}`}>{PROFESSORS[id].name}</p>
              <p className="text-sm text-muted">{PROFESSORS[id].tagline}</p>
            </div>
          </div>
        ))}
      </section>

      <div className="space-y-6 rounded-3xl bg-white p-6 shadow-sm ring-1 ring-black/5 sm:p-8">
        {/* 1. Slides */}
        <div>
          <h2 className="mb-2 font-semibold"><span className="text-muted">1.</span> Your lecture slides</h2>
          <button
            type="button"
            onClick={() => inputRef.current?.click()}
            onDragOver={(e) => { e.preventDefault(); setDragging(true) }}
            onDragLeave={() => setDragging(false)}
            onDrop={(e) => { e.preventDefault(); setDragging(false); pick(e.dataTransfer.files[0]) }}
            className={`flex w-full flex-col items-center justify-center rounded-2xl border-2 border-dashed px-4 py-8 text-center transition ${
              dragging ? 'border-theorist bg-theorist-soft' : file ? 'border-practitioner bg-practitioner-soft' : 'border-black/15 hover:border-theorist hover:bg-theorist-soft/50'
            }`}
          >
            {file ? (
              <>
                <span className="font-semibold text-practitioner">✓ {file.name}</span>
                <span className="mt-1 text-sm text-muted">{(file.size / 1024 / 1024).toFixed(1)} MB · click to choose a different file</span>
              </>
            ) : (
              <>
                <span className="font-semibold">Drop your PDF here, or click to browse</span>
                <span className="mt-1 text-sm text-muted">The professors only ask about what's in your slides</span>
              </>
            )}
          </button>
          <input ref={inputRef} type="file" accept="application/pdf,.pdf" className="sr-only" onChange={(e) => pick(e.target.files?.[0])} />
        </div>

        <div className="grid gap-6 sm:grid-cols-2">
          {/* 2. Date */}
          <div>
            <label htmlFor="exam-date" className="mb-2 block font-semibold"><span className="text-muted">2.</span> When is your real exam?</label>
            <input
              id="exam-date"
              type="date"
              min={today}
              value={examDate}
              onChange={(e) => setExamDate(e.target.value)}
              className="w-full rounded-xl border border-black/15 px-3 py-2.5"
            />
            <p className="mt-1.5 text-sm text-muted">
              {days === null ? 'Optional: we use it to plan your revision.' : days <= 0 ? "That's today. Good luck!" : `${days} day${days === 1 ? '' : 's'} to go, plenty of time to prepare.`}
            </p>
          </div>

          {/* 3. Language */}
          <fieldset>
            <legend className="mb-2 font-semibold"><span className="text-muted">3.</span> Exam language</legend>
            <div className="grid grid-cols-2 gap-2">
              {(['en', 'de'] as Language[]).map((l) => (
                <label key={l} className={`cursor-pointer rounded-xl border px-3 py-2.5 text-center font-medium transition ${language === l ? 'border-theorist bg-theorist-soft text-theorist' : 'border-black/15 hover:bg-black/[0.02]'}`}>
                  <input type="radio" name="lang" value={l} checked={language === l} onChange={() => setLanguage(l)} className="sr-only" />
                  {l === 'en' ? 'English' : 'Deutsch'}
                </label>
              ))}
            </div>
          </fieldset>
        </div>

        {/* 4. Length */}
        <fieldset>
          <legend className="mb-2 font-semibold"><span className="text-muted">4.</span> How long?</legend>
          <div className="grid grid-cols-3 gap-2">
            {LENGTHS.map((o) => (
              <label key={o.n} className={`cursor-pointer rounded-xl border px-3 py-3 text-center transition ${length === o.n ? 'border-theorist bg-theorist-soft' : 'border-black/15 hover:bg-black/[0.02]'}`}>
                <input type="radio" name="length" value={o.n} checked={length === o.n} onChange={() => setLength(o.n)} className="sr-only" />
                <span className={`block font-semibold ${length === o.n ? 'text-theorist' : ''}`}>{o.label}</span>
                <span className="block text-sm text-muted">{o.n} questions · {o.hint}</span>
              </label>
            ))}
          </div>
        </fieldset>

        {/* 5. Mic */}
        <MicCheck />

        {error && <p role="alert" className="rounded-xl bg-skeptic-soft px-4 py-3 text-skeptic">{error}</p>}

        <button
          type="button"
          disabled={!file}
          onClick={start}
          className="w-full rounded-2xl bg-ink px-6 py-4 text-lg font-semibold text-white shadow-sm transition hover:bg-black disabled:cursor-not-allowed disabled:opacity-30"
        >
          {file ? 'Start my exam' : 'Add your slides to begin'}
        </button>
        <p className="text-center text-sm text-muted">It's practice. Mistakes here are how you get better.</p>
      </div>
    </div>
  )
}

function MicCheck() {
  const [state, setState] = useState<'idle' | 'testing' | 'ok' | 'denied'>('idle')
  const [level, setLevel] = useState(0)
  const [heard, setHeard] = useState(false)
  const rec = useRef<WavRecorder | null>(null)

  useEffect(() => () => rec.current?.close(), [])

  const test = async () => {
    try {
      rec.current = new WavRecorder()
      rec.current.onLevel = (l) => {
        setLevel(l)
        if (l > 0.15) setHeard(true)
      }
      await rec.current.init()
      setState('testing')
      setTimeout(() => {
        rec.current?.close()
        setState('ok')
        setLevel(0)
      }, 6000)
    } catch {
      setState('denied')
    }
  }

  return (
    <div>
      <h2 className="mb-2 font-semibold"><span className="text-muted">5.</span> Mic check <span className="font-normal text-muted">(optional, you can also type)</span></h2>
      <div className="flex flex-wrap items-center gap-3">
        <button type="button" onClick={test} disabled={state === 'testing'} className="rounded-xl border border-black/15 px-4 py-2.5 font-medium hover:bg-black/[0.03] disabled:opacity-60">
          {state === 'testing' ? 'Say something…' : 'Test my microphone'}
        </button>
        {state === 'testing' && (
          <div className="h-3 w-40 overflow-hidden rounded-full bg-black/5" aria-label="Microphone level">
            <div className="h-full rounded-full bg-practitioner transition-[width] duration-75" style={{ width: `${level * 100}%` }} />
          </div>
        )}
        <span aria-live="polite" className="text-sm">
          {state === 'testing' && heard && <span className="text-practitioner">✓ We can hear you</span>}
          {state === 'ok' && (heard ? <span className="text-practitioner">✓ Your mic works</span> : <span className="text-skeptic">We didn't hear much. Check your input device, or type your answers.</span>)}
          {state === 'denied' && <span className="text-skeptic">Microphone blocked. Allow it in your browser, or type your answers instead.</span>}
        </span>
      </div>
    </div>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { sendAnswer, type Assessment, type SessionResponse, type Turn } from './api'
import { WavRecorder } from './recorder'
import { Avatar, PROFESSOR_IDS, PROFESSORS, SpeakingBars, ThinkingDots } from './professors'

type Phase = 'speaking' | 'listening' | 'recording' | 'conferring'

interface Exchange {
  turn: Turn
  answer: string
}

export default function Exam({ session, onFinish }: { session: SessionResponse; onFinish: () => void }) {
  const [turn, setTurn] = useState<Turn>(session.turn)
  const [phase, setPhase] = useState<Phase>('speaking')
  const [history, setHistory] = useState<Exchange[]>([])
  const [notes, setNotes] = useState<{ assessments: Assessment[]; reasoning: string } | null>(null)
  const [showNotes, setShowNotes] = useState(true)
  const [typing, setTyping] = useState(false)
  const [typed, setTyped] = useState('')
  const [error, setError] = useState('')
  const [hint, setHint] = useState('')
  const [needsTap, setNeedsTap] = useState(false)
  const [level, setLevel] = useState(0)

  const audio = useRef<HTMLAudioElement>(new Audio())
  const recorder = useRef<WavRecorder | null>(null)
  const phaseRef = useRef<Phase>(phase)
  phaseRef.current = phase

  // Play each new question in the speaker's voice.
  const play = useCallback(() => {
    const a = audio.current
    setNeedsTap(false)
    setPhase('speaking')
    a.src = turn.audio_url
    a.onended = () => setPhase('listening')
    a.onerror = () => setPhase('listening')
    a.play().catch(() => {
      setNeedsTap(true)
      setPhase('listening')
    })
  }, [turn])

  useEffect(() => {
    play()
  }, [play])

  useEffect(() => {
    const a = audio.current
    return () => {
      a.pause()
      recorder.current?.close()
    }
  }, [])

  const submit = useCallback(
    async (answer: { audio?: Blob; text?: string; skip?: boolean }) => {
      setPhase('conferring')
      setError('')
      setHint('')
      try {
        const res = await sendAnswer(session.session_id, answer)
        setHistory((h) => [...h, { turn, answer: res.transcript }])
        setNotes({ assessments: res.assessments, reasoning: res.turn.reasoning })
        setTyped('')
        setTyping(false)
        setTurn(res.turn)
      } catch (e) {
        setError((e as Error).message)
        setPhase('listening')
      }
    },
    [session.session_id, turn],
  )

  const startRecording = useCallback(async () => {
    if (phaseRef.current === 'conferring' || phaseRef.current === 'recording' || turn.end_exam) return
    audio.current.pause()
    setError('')
    setHint('')
    try {
      if (!recorder.current) {
        recorder.current = new WavRecorder()
        recorder.current.onLevel = setLevel
      }
      await recorder.current.start()
      setPhase('recording')
    } catch {
      setError('We could not access your microphone. Allow it in the browser, or type your answer instead.')
      setTyping(true)
      setPhase('listening')
    }
  }, [turn.end_exam])

  const stopRecording = useCallback(() => {
    if (phaseRef.current !== 'recording' || !recorder.current) return
    const { wav, seconds } = recorder.current.stop()
    setLevel(0)
    if (seconds < 0.7) {
      setHint('Hold the button (or Space) the whole time you speak, then let go.')
      setPhase('listening')
      return
    }
    submit({ audio: wav })
  }, [submit])

  // Hold Space to talk (unless the student is typing).
  useEffect(() => {
    const isField = (e: KeyboardEvent) => (e.target as HTMLElement)?.closest('textarea, input, button')
    const down = (e: KeyboardEvent) => {
      if (e.code !== 'Space' || e.repeat || isField(e)) return
      e.preventDefault()
      startRecording()
    }
    const up = (e: KeyboardEvent) => {
      if (e.code !== 'Space' || isField(e)) return
      e.preventDefault()
      stopRecording()
    }
    window.addEventListener('keydown', down)
    window.addEventListener('keyup', up)
    return () => {
      window.removeEventListener('keydown', down)
      window.removeEventListener('keyup', up)
    }
  }, [startRecording, stopRecording])

  const speaker = PROFESSORS[turn.speaker]
  const answered = history.length
  const progress = Math.min(1, answered / turn.total_questions)
  const lastAnswer = history.at(-1)?.answer

  return (
    <div className="mx-auto max-w-5xl px-4 pb-16 pt-6 sm:pt-10">
      {/* Header */}
      <header className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <p className="text-sm font-medium text-muted">{session.blueprint.course_title}</p>
          <span className="mt-1.5 inline-block rounded-full bg-white px-3 py-1 text-sm font-medium shadow-sm ring-1 ring-black/5">
            Topic: {turn.topic_title}
          </span>
        </div>
        <div className="sm:w-64">
          <p className="mb-1.5 text-sm font-medium sm:text-right">
            {turn.end_exam ? 'All questions answered' : `Question ${turn.question_number} of ${turn.total_questions}`}
          </p>
          <div className="h-2 overflow-hidden rounded-full bg-black/5" role="progressbar" aria-valuemin={0} aria-valuemax={turn.total_questions} aria-valuenow={answered}>
            <div className="h-full rounded-full bg-practitioner transition-all duration-700" style={{ width: `${progress * 100}%` }} />
          </div>
        </div>
      </header>

      {/* Panel */}
      <section aria-label="Exam panel" className="grid grid-cols-3 gap-2 sm:gap-4">
        {PROFESSOR_IDS.map((id) => {
          const p = PROFESSORS[id]
          const active = id === turn.speaker && phase !== 'conferring'
          return (
            <div
              key={id}
              className={`flex flex-col items-center rounded-2xl bg-white p-3 text-center shadow-sm ring-1 transition-all duration-300 sm:p-5 ${
                active ? `ring-2 ${p.ring} scale-[1.03] shadow-md` : 'ring-black/5'
              } ${!active && phase !== 'conferring' ? 'opacity-60' : ''}`}
            >
              <Avatar id={id} size="lg" />
              <p className={`mt-2 text-sm font-semibold sm:text-base ${p.text}`}>{p.name}</p>
              <p className="hidden text-xs text-muted sm:block">{p.style}</p>
              <div className={`mt-2 h-5 text-xs font-medium ${p.text}`} aria-hidden>
                {phase === 'conferring' ? <ThinkingDots /> : active && phase === 'speaking' ? <SpeakingBars /> : null}
              </div>
            </div>
          )
        })}
      </section>

      {/* Caption */}
      <section aria-live="polite" className={`mt-6 rounded-3xl border-l-4 bg-white p-5 shadow-sm ring-1 ring-black/5 sm:p-7 ${phase === 'conferring' ? 'border-black/10' : speaker.border}`}>
        {phase === 'conferring' ? (
          <div className="flex items-center gap-3 text-lg text-muted">
            <ThinkingDots /> The panel is conferring…
          </div>
        ) : (
          <>
            <div className="mb-2 flex items-center justify-between gap-2">
              <p className={`font-semibold ${speaker.text}`}>{speaker.name}</p>
              <button type="button" onClick={play} className="rounded-lg px-2.5 py-1 text-sm font-medium text-muted hover:bg-black/5">
                ↻ Replay
              </button>
            </div>
            <p className="font-display text-xl leading-snug sm:text-2xl">{turn.question}</p>
            {needsTap && (
              <button type="button" onClick={play} className={`mt-3 rounded-xl ${speaker.soft} ${speaker.text} px-4 py-2 font-medium`}>
                ▶ Tap to hear the question
              </button>
            )}
          </>
        )}
      </section>

      {lastAnswer && phase !== 'conferring' && (
        <div className="mt-3 flex justify-end">
          <p className="max-w-[85%] rounded-2xl rounded-br-sm bg-ink/90 px-4 py-2.5 text-sm text-white">
            <span className="mb-0.5 block text-xs text-white/60">Your last answer</span>
            {lastAnswer}
          </p>
        </div>
      )}

      {/* Controls */}
      <section className="mt-8 flex flex-col items-center" aria-label="Answer controls">
        {turn.end_exam ? (
          <button type="button" onClick={onFinish} className="rounded-2xl bg-ink px-8 py-4 text-lg font-semibold text-white shadow-sm hover:bg-black">
            See my results →
          </button>
        ) : typing ? (
          <form
            className="w-full max-w-2xl"
            onSubmit={(e) => {
              e.preventDefault()
              if (typed.trim()) submit({ text: typed })
            }}
          >
            <label htmlFor="typed" className="sr-only">Your answer</label>
            <textarea
              id="typed"
              autoFocus
              rows={3}
              value={typed}
              onChange={(e) => setTyped(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault()
                  if (typed.trim()) submit({ text: typed })
                }
              }}
              placeholder="Type your answer as you would say it…"
              className="w-full rounded-2xl border border-black/15 bg-white p-4 text-lg shadow-sm"
              disabled={phase === 'conferring'}
            />
            <div className="mt-2 flex justify-between">
              <button type="button" onClick={() => setTyping(false)} className="rounded-xl px-3 py-2 text-sm font-medium text-muted hover:bg-black/5">
                🎙 Use my voice instead
              </button>
              <button type="submit" disabled={!typed.trim() || phase === 'conferring'} className="rounded-xl bg-ink px-5 py-2 font-semibold text-white disabled:opacity-30">
                Send answer
              </button>
            </div>
          </form>
        ) : (
          <>
            <div className="relative">
              {phase === 'recording' && (
                <span aria-hidden className="mic-ripple absolute inset-0 rounded-full bg-skeptic" style={{ transform: `scale(${1 + level * 0.5})` }} />
              )}
              <button
                type="button"
                aria-label={phase === 'recording' ? 'Recording. Release to send your answer' : 'Hold to record your answer'}
                disabled={phase === 'conferring'}
                onPointerDown={(e) => { e.preventDefault(); startRecording() }}
                onPointerUp={stopRecording}
                onPointerLeave={stopRecording}
                onContextMenu={(e) => e.preventDefault()}
                className={`relative grid h-24 w-24 touch-none select-none place-items-center rounded-full text-white shadow-lg transition ${
                  phase === 'recording' ? 'scale-110 bg-skeptic' : 'bg-ink hover:scale-105'
                } disabled:opacity-30`}
              >
                <MicIcon />
              </button>
            </div>
            <p className="mt-4 text-center font-medium" aria-live="polite">
              {phase === 'recording' && 'Listening… release when you are done'}
              {phase === 'speaking' && 'Listen to the question…'}
              {phase === 'listening' && 'Take a moment to think. Then hold Space (or the button) and answer.'}
              {phase === 'conferring' && 'Your answer is with the panel.'}
            </p>
            {hint && <p className="mt-1 text-sm text-skeptic">{hint}</p>}
          </>
        )}

        {error && <p role="alert" className="mt-4 rounded-xl bg-skeptic-soft px-4 py-3 text-skeptic">{error}</p>}

        {!turn.end_exam && (
          <div className="mt-5 flex flex-wrap justify-center gap-2">
            {!typing && (
              <button type="button" onClick={() => setTyping(true)} disabled={phase === 'conferring'} className="rounded-xl border border-black/10 bg-white px-4 py-2 text-sm font-medium hover:bg-black/[0.03] disabled:opacity-40">
                ⌨ Type instead
              </button>
            )}
            <button type="button" onClick={() => submit({ skip: true })} disabled={phase === 'conferring'} className="rounded-xl border border-black/10 bg-white px-4 py-2 text-sm font-medium hover:bg-black/[0.03] disabled:opacity-40">
              I'm not sure, next question
            </button>
          </div>
        )}
      </section>

      {/* Panel notes: the multi-agent reasoning behind each turn */}
      {notes && (
        <section className="mt-10">
          <button type="button" onClick={() => setShowNotes((s) => !s)} className="text-sm font-semibold text-muted hover:text-ink" aria-expanded={showNotes}>
            {showNotes ? '▾' : '▸'} Panel notes: how the professors judged your last answer
          </button>
          {showNotes && (
            <div className="mt-3 grid gap-3 sm:grid-cols-3">
              {notes.assessments.map((a) => (
                <div key={a.professor} className="rounded-2xl bg-white p-4 text-sm shadow-sm ring-1 ring-black/5">
                  <div className="mb-2 flex items-center gap-2">
                    <Avatar id={a.professor} size="sm" />
                    <span className={`font-semibold ${PROFESSORS[a.professor].text}`}>{PROFESSORS[a.professor].name}</span>
                  </div>
                  <Meter label="Score" value={a.score_0_to_10 / 10} text={`${a.score_0_to_10}/10`} color="bg-practitioner" />
                  <Meter label="Bluff signal" value={a.bluff_signal} text={a.bluff_signal.toFixed(2)} color={a.bluff_signal > 0.6 ? 'bg-skeptic' : 'bg-black/30'} />
                  <p className="mt-2 text-muted"><span className="font-medium text-ink">Good: </span>{a.what_was_good}</p>
                  {a.gaps[0] && <p className="mt-1 text-muted"><span className="font-medium text-ink">Gap: </span>{a.gaps[0]}</p>}
                </div>
              ))}
              <p className="text-sm text-muted sm:col-span-3"><span className="font-semibold text-ink">Chair: </span>{notes.reasoning}</p>
            </div>
          )}
        </section>
      )}
    </div>
  )
}

function Meter({ label, value, text, color }: { label: string; value: number; text: string; color: string }) {
  return (
    <div className="mt-1.5">
      <div className="flex justify-between text-xs text-muted"><span>{label}</span><span>{text}</span></div>
      <div className="mt-0.5 h-1.5 overflow-hidden rounded-full bg-black/5">
        <div className={`h-full rounded-full ${color}`} style={{ width: `${Math.round(value * 100)}%` }} />
      </div>
    </div>
  )
}

function MicIcon() {
  return (
    <svg aria-hidden width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="9" y="2" width="6" height="12" rx="3" />
      <path d="M5 10v1a7 7 0 0 0 14 0v-1M12 18v4M8 22h8" />
    </svg>
